// Client-side tools for the question tables generated by hooks/questions.py (UI322, UI323):
// - segmented filter groups (one active choice per group), the browser's own solved /
//   favourite marks among them, the topics with the most common ones inline and the rest
//   behind "more topics" with a search field, and a text search over the title, the
//   topics (in both names) and the id;
// - the active filters as removable chips above the table with the count, and when no row
//   is left a note with the filter whose removal brings rows back;
// - on phones the filters fold behind one "filter (n)" button;
// - the filters, the search and the sort kept in the address (replaced, not pushed, so
//   "back" leaves the page): a filtered table can be linked and survives a reload;
// - sorting by a column (header buttons on wide screens, a select on phones, kept in sync);
// - a topic in a row filters the table by it, "+n" shows the row's other topics;
// - a "random question" button that opens one of the rows left after filtering;
// - the solved / favourite marks next to each title, and on the row as classes.
document.addEventListener("DOMContentLoaded", () => {
  const marks = window.dvqMarks || { has: () => false };
  const collator = new Intl.Collator("he");
  const NB = " ";
  const PARAMS = ["level", "difficulty", "kind", "mark", "tag"];
  const TEXT = "find";                                   // not "q": the theme's search opens on ?q=

  document.querySelectorAll(".question-filter").forEach((filterBox, index) => {
    const wrap = filterBox.nextElementSibling;          // .questions-wrap
    const table = wrap && wrap.querySelector("table");
    if (!table) return;
    const tbody = table.querySelector("tbody");
    const none = wrap.nextElementSibling && wrap.nextElementSibling.classList.contains("questions-none") ? wrap.nextElementSibling : null;
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const groups = Array.from(filterBox.querySelectorAll(".filter-group"));
    const byName = Object.fromEntries(groups.map((g) => [g.dataset.filter, g]));
    const search = filterBox.querySelector("input[data-filter='text']");
    const sortSelect = filterBox.querySelector(".filter-sort select");
    const headers = Array.from(table.querySelectorAll("th[data-sort]"));
    const randomBtn = filterBox.querySelector(".filter-random");
    const toggle = filterBox.querySelector(".filter-toggle");
    const active = filterBox.querySelector(".filter-active");
    const counter = filterBox.querySelector(".filter-count");
    const useUrl = index === 0;                          // one table per page keeps the address
    let sortKey = "id", sortDir = 1;
    let order = [];                                      // the active groups, oldest first

    const visible = () => rows.filter((r) => !r.hidden);
    const chipOf = (name, value) => {
      const g = byName[name];
      return g ? Array.from(g.querySelectorAll(".filter-chip")).find((c) => c.dataset.value === value) : null;
    };
    const labelOf = (name) => (byName[name] ? byName[name].querySelector(".filter-label").textContent.trim() : name);

    const setGroup = (name, value) => {
      const g = byName[name];
      if (!g) return;
      if (!chipOf(name, value)) value = "";              // an unknown value from an old link
      g.dataset.value = value;
      g.querySelectorAll(".filter-chip").forEach((c) => {
        const on = c.dataset.value === value;
        c.classList.toggle("is-active", on);
        c.setAttribute("aria-pressed", String(on));
      });
      order = order.filter((n) => n !== name);
      if (value) order.push(name);
    };

    // The reader's marks of a row: a check in a green disc and an amber star, named for a
    // screen reader; the row also carries .is-solved / .is-star (17-lists.css)
    const SOLVED = '<span class="q-mark q-mark-solved" role="img" aria-label="סימנת כפתורה" title="סימנת כפתורה">' +
      '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M4 8.4l2.6 2.6L12 5.6"/></svg></span>';
    const STAR = '<span class="q-mark q-mark-star" role="img" aria-label="מועדף" title="מועדף">' +
      '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 1.6l1.9 4 4.4.5-3.3 3 .9 4.3L8 11.2l-3.9 2.2.9-4.3-3.3-3 4.4-.5z"/></svg></span>';
    const paintMarks = () => {
      rows.forEach((row) => {
        const slot = row.querySelector(".q-marks");
        if (!slot) return;
        const id = row.dataset.id;
        const solved = marks.has(id, "solved"), star = marks.has(id, "star");
        row.classList.toggle("is-solved", solved);
        row.classList.toggle("is-star", star);
        slot.innerHTML = (solved ? SOLVED : "") + (star ? STAR : "");
      });
    };

    const current = () => {
      const f = {};
      groups.forEach((g) => { if (g.dataset.value) f[g.dataset.filter] = g.dataset.value; });
      return { f, text: search ? search.value.trim().toLowerCase() : "" };
    };
    // "46" finds 0046; any other text is looked up in the title, the topics and the id
    const matches = (row, f, text) => {
      const id = row.dataset.id;
      return (!f.level || row.dataset.level === f.level) &&
        (!f.difficulty || row.dataset.difficulty === f.difficulty) &&
        (!f.kind || row.dataset.kind === f.kind) &&
        (!f.tag || row.dataset.tags.split(" ").includes(f.tag)) &&
        (!f.mark || (f.mark === "star" ? marks.has(id, "star") : f.mark === "solved" ? marks.has(id, "solved") : !marks.has(id, "solved"))) &&
        (!text || (/^\d+$/.test(text) && Number(text) === Number(id)) || row.dataset.search.includes(text));
    };
    const countWith = (f, text) => rows.filter((r) => matches(r, f, text)).length;

    const button = (cls, text, onClick, label) => {
      const b = document.createElement("button");
      b.type = "button";
      b.className = cls;
      b.textContent = text;
      if (label) b.setAttribute("aria-label", label);
      b.addEventListener("click", onClick);
      return b;
    };
    const clearAll = () => {
      PARAMS.forEach((n) => setGroup(n, ""));
      if (search) search.value = "";
      apply();
    };
    // the active filters as chips, newest last; the search text is one of them
    const filtersNow = () => {
      const { text } = current();
      const list = order.map((name) => {
        const short = chipOf(name, byName[name].dataset.value).textContent.trim();
        return { name, short: `"${short}"`, label: `${labelOf(name)}${NB}: ${short}`, drop: () => setGroup(name, "") };
      });
      if (text) list.push({ name: "text", short: "החיפוש", label: `חיפוש${NB}: "${search.value.trim()}"`, drop: () => { search.value = ""; } });
      return list;
    };

    const paintActive = (shown, solved, list) => {
      active.querySelectorAll(".fa-chip, .fa-clear").forEach((el) => el.remove());
      list.forEach((it) => active.insertBefore(button("fa-chip", `${it.label} ×`, () => { it.drop(); apply(); }, `הסרת המסנן ${it.label}`), counter));
      if (list.length > 1) active.insertBefore(button("fa-clear", "נקה הכל", clearAll), counter);
      counter.textContent = `מוצגות ${shown} מתוך ${rows.length} שאלות` + (solved ? ` · סימנת ${solved} כפתורות` : "");
      active.classList.toggle("has-filters", list.length > 0);
    };

    // No row left: name the filter whose removal brings back the most rows, and the
    // last one chosen, and offer to clear them all
    const paintNone = (shown, list) => {
      if (!none) return;
      wrap.hidden = shown === 0;
      none.hidden = shown !== 0;
      if (shown) return;
      none.replaceChildren();
      const p = document.createElement("p");
      p.className = "qn-text";
      p.textContent = "אין שאלות שעונות על כל המסננים.";
      none.append(p);
      const { f, text } = current();
      const without = (it) => it.name === "text" ? countWith(f, "") : countWith({ ...f, [it.name]: "" }, text);
      let best = null;
      list.forEach((it) => { const n = without(it); if (n && (!best || n > best.n)) best = { it, n }; });
      const actions = document.createElement("div");
      actions.className = "qn-actions";
      if (best) actions.append(button("qn-btn qn-best", `בלי ${best.it.short} יש ${best.n} ${best.n === 1 ? "שאלה" : "שאלות"}`, () => { best.it.drop(); apply(); }));
      const last = list[list.length - 1];
      if (last && (!best || best.it !== last)) actions.append(button("qn-btn", `הסרת המסנן האחרון, ${last.short}`, () => { last.drop(); apply(); }));
      if (list.length) actions.append(button("qn-btn", "נקה הכל", clearAll));
      none.append(actions);
    };

    const writeUrl = () => {
      if (!useUrl || !window.history || !history.replaceState) return;
      const params = new URLSearchParams(location.search);
      const { f } = current();
      PARAMS.forEach((n) => { if (f[n]) params.set(n, f[n]); else params.delete(n); });
      if (search && search.value.trim()) params.set(TEXT, search.value.trim()); else params.delete(TEXT);
      if (sortKey !== "id" || sortDir !== 1) params.set("sort", `${sortDir < 0 ? "-" : ""}${sortKey}`); else params.delete("sort");
      const qs = params.toString();
      const url = `${location.pathname}${qs ? `?${qs}` : ""}${location.hash}`;
      if (url !== `${location.pathname}${location.search}${location.hash}`) history.replaceState(history.state, "", url);
    };

    const apply = () => {
      const { f, text } = current();
      let shown = 0, solved = 0;
      rows.forEach((row) => {
        const ok = matches(row, f, text);
        row.hidden = !ok;
        if (ok) shown++;
        if (marks.has(row.dataset.id, "solved")) solved++;
      });
      const list = filtersNow();
      paintActive(shown, solved, list);
      paintNone(shown, list);
      if (toggle) toggle.querySelector(".filter-n").textContent = order.length ? ` (${order.length})` : "";
      if (randomBtn) randomBtn.disabled = shown === 0;
      writeUrl();
    };

    // Sort key of a row; ties (same level or difficulty) always keep the ids ascending
    const value = (row, key) => {
      if (key === "title") return row.querySelector(".q-title a").textContent.trim();
      if (key === "level") return Number(row.dataset.levelRank);
      if (key === "difficulty") return Number(row.dataset.diffRank);
      return Number(row.dataset.id);
    };

    const sort = (key, dir) => {
      if (!headers.some((th) => th.dataset.sort === key)) key = "id";
      sortKey = key; sortDir = dir;
      const sorted = rows.slice().sort((a, b) => {
        const va = value(a, key), vb = value(b, key);
        const primary = typeof va === "string" ? collator.compare(va, vb) : va - vb;
        return dir * primary || Number(a.dataset.id) - Number(b.dataset.id);
      });
      sorted.forEach((r) => tbody.appendChild(r));
      headers.forEach((th) => {
        th.setAttribute("aria-sort", th.dataset.sort === key ? (dir > 0 ? "ascending" : "descending") : "none");
      });
      if (sortSelect) sortSelect.value = key;
    };

    headers.forEach((th) => {
      th.querySelector(".th-sort").addEventListener("click", () => {
        sort(th.dataset.sort, th.dataset.sort === sortKey ? -sortDir : 1);
        writeUrl();
      });
    });
    if (sortSelect) sortSelect.addEventListener("change", () => { sort(sortSelect.value, 1); writeUrl(); });

    groups.forEach((g) => {
      g.addEventListener("click", (e) => {
        const chip = e.target.closest(".filter-chip");
        if (!chip) return;
        setGroup(g.dataset.filter, chip.dataset.value);
        apply();
      });
    });
    if (search) search.addEventListener("input", apply);

    // The topics behind "more topics", with a search over both names
    const topics = byName.tag;
    const more = topics && topics.querySelector(".topics-more");
    if (more) {
      const moreBtn = topics.querySelector(".topics-toggle");
      const find = more.querySelector(".topics-search");
      moreBtn.addEventListener("click", () => {
        more.hidden = !more.hidden;
        moreBtn.setAttribute("aria-expanded", String(!more.hidden));
        if (!more.hidden) find.focus();
      });
      find.addEventListener("input", () => {
        const t = find.value.trim().toLowerCase();
        let left = 0;
        more.querySelectorAll(".filter-chip").forEach((c) => {
          const ok = !t || c.textContent.toLowerCase().includes(t) || (c.dataset.en || "").includes(t);
          c.hidden = !ok;
          if (ok) left++;
        });
        more.querySelector(".topics-none").hidden = left > 0;
      });
    }

    // A topic in a row filters by it; "+n" shows the row's other topics
    tbody.addEventListener("click", (e) => {
      const topic = e.target.closest(".q-topic");
      if (topic) { setGroup("tag", topic.dataset.tag); apply(); return; }
      const plus = e.target.closest(".q-more");
      if (plus) {
        const rest = plus.nextElementSibling;
        rest.hidden = false;
        plus.hidden = true;
        const first = rest.querySelector("button");
        if (first) first.focus();
      }
    });

    // Phones: the filters fold behind one button
    if (toggle) {
      toggle.addEventListener("click", () => {
        const open = !filterBox.classList.contains("is-open");
        filterBox.classList.toggle("is-open", open);
        toggle.setAttribute("aria-expanded", String(open));
      });
    }

    if (randomBtn) {
      randomBtn.addEventListener("click", () => {
        const pool = visible();
        if (!pool.length) return;
        const row = pool[Math.floor(Math.random() * pool.length)];
        window.location.href = row.querySelector(".q-title a").href;
      });
    }

    // The address: filters, search and sort from a link or a reload
    let start = ["id", 1];
    if (useUrl) {
      const params = new URLSearchParams(location.search);
      PARAMS.forEach((n) => { if (params.get(n)) setGroup(n, params.get(n)); });
      if (search && params.get(TEXT)) search.value = params.get(TEXT);
      const s = params.get("sort");
      if (s) start = [s.replace(/^-/, ""), s.startsWith("-") ? -1 : 1];
      if (order.includes("tag") && more && topics.querySelector(".topics-more .is-active")) {
        more.hidden = false;
        topics.querySelector(".topics-toggle").setAttribute("aria-expanded", "true");
      }
    }

    document.addEventListener("dvq-marks", () => { paintMarks(); apply(); });
    paintMarks();
    sort(start[0], start[1]);
    apply();
  });
});
